    # S = {r1, ..., r7}, T = {c1, ..., c7}
    # S+T = {r+c : r in S, c in T}
    # If S = {r1, ..., r7} and T = {c1, ..., c7} are such that S+T = {1, ..., 49}
    # then for any r in S and c in T, r+c is in {1, ..., 49}.
    # Let's write a more general script to find all S, T.

    # From the previous reasoning:
    # r1 = 0, c1 = 1
    # {c2, ..., c7, r2+1, ..., r7+1} = {2, ..., 13}
    # Let R_rest = {r2+1, ..., r7+1} and C_rest = {c2, ..., c7}
    # R_rest and C_rest are disjoint subsets of {2, ..., 13}
    # and their union is {2, ..., 13}.
    # Number of such pairs is binom(12, 6) = 924.
    # For each such pair, we check if S+T = {1, ..., 49}.

    count = 0
    possible_elements = list(range(2, 14))
    for R_rest in itertools.combinations(possible_elements, 6):
        C_rest = [x for x in possible_elements if x not in R_rest]

        S = [0] + [x - 1 for x in R_rest]
        T = [1] + list(C_rest)

        sums = set()
        for r in S:
            for c in T:
                sums.add(r + c)

        if len(sums) == 49:
            count += 1

    return count

